  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL REFERENCES projects(id),
  task_id      TEXT REFERENCES tasks(id),
  agent_id     TEXT,
  kind         TEXT NOT NULL DEFAULT 'discovery',
  content      TEXT NOT NULL,
  created_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO learnings VALUES('c-zc89','p-wl1l','t-oxd8','default','constraint','SDK contract: public surface is crates/chief-sdk plus packages/chief-sdk-ts; packs must not import kernel crates; CapabilityContext is the only outside-world handle; CapabilityKind is closed and adding kinds requires ADR; every grant has typed scope and non-empty usage_reason shown at consent; v0 starts at 0.1.0; first dogfood pack should use public SDK only.','2026-04-21 22:49:16');
INSERT INTO learnings VALUES('c-ybfa','p-wl1l','t-relc','default','constraint','OS boundary contract: packs request identity/money/picker/device/time/agent-autonomy primitives, OS renders ceremonies and returns opaque handles. Sensitive surfaces like OAuth, file/contact/share pickers, ceremonies, Trust Ledger, Omnibar, status strip remain OS-exclusive; SDK should expose request/grant shapes without giving packs raw tokens, device keys, or OS surfaces.','2026-04-21 22:49:36');
INSERT INTO learnings VALUES('c-a09r','p-wl1l','t-0cjj','default','constraint','ADR-0010 stability contract: SDK is the semver boundary; version starts at 0.1.0; breaking changes require major bump plus at least one minor release deprecation window; closed CapabilityKind additions require ADR; first-party packs must dogfood public SDK only; no kernel crate imports or private entitlements.','2026-04-21 22:49:41');
INSERT INTO learnings VALUES('c-0uit','p-wl1l','t-u085','default','pattern','Workspace pattern: root Cargo workspace uses resolver=2, edition/rust-version/license/repository/publish from workspace.package, serde/tokio/async-trait/thiserror/chrono in workspace.dependencies. Existing TS prototype uses ESM, TypeScript 5.6, React 18. Commit format requires Co-Authored-By. No docs/coding-style.md file found by search; apply requested local constraints directly.','2026-04-21 22:50:06');
